from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.adjustments import refund
from ledgerly.errors import BillingError

T0 = datetime(2026, 1, 1, tzinfo=timezone.utc)

def mk(status="captured", amt="100.00"):
    return Payment("pay_1", "inv_1", Decimal(amt), status=status, created_at=T0, captured_at=T0)

# partial then full
p = mk()
assert refund(p, "40.00", T0) is p
assert p.refunded_amount == Decimal("40.00") and p.status == "captured"
refund(p, Decimal("60.00"), T0)
assert p.refunded_amount == Decimal("100.00") and p.status == "refunded"

# over-refund
p = mk()
refund(p, "60.00", T0)
try:
    refund(p, "50.00", T0); raise AssertionError("should fail")
except BillingError as e:
    assert e.code == "refund_exceeds_captured", e.code

# non-captured
for st in ("authorized", "voided", "refunded"):
    try:
        refund(mk(st), "1.00", T0); raise AssertionError(st)
    except BillingError as e:
        assert e.code == "invalid_state", e.code

# non-positive
for a in ("0.00", "-1.00"):
    try:
        refund(mk(), a, T0); raise AssertionError(a)
    except BillingError as e:
        assert e.code == "non_positive_amount", e.code

# naive datetime
try:
    refund(mk(), "1.00", datetime(2026,1,1)); raise AssertionError("naive")
except BillingError as e:
    assert e.code == "naive_datetime", e.code

print("all edge cases OK")
EOF"}

